function d_nas_sample(P,R){var n=P.n||24,cands=[];for(var i=0;i<n;i++){var layers=2+Math.floor(R()*6),width=32*Math.pow(2,Math.floor(R()*4));var score=0.5+0.3*R()-0.02*layers-0.0001*width/64;cands.push({layers:layers,width:width,proxy_score:+score.toFixed(4)});}cands.sort(function(a,b){return b.proxy_score-a.proxy_score;});return{sampled:n,best:cands[0],top3:cands.slice(0,3)};}

